DROP TABLE IF EXISTS `processo_administrativo_extrajudicial`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `processo_administrativo_extrajudicial` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `processo_administrativo_id` int unsigned NOT NULL,
  `processo_extrajudicial_id` int unsigned NOT NULL,
  `data_vinculo` date NOT NULL DEFAULT (curdate()),
  `observacao` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `criado_por` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pae_par` (`processo_administrativo_id`,`processo_extrajudicial_id`),
  KEY `ix_pae_extrajudicial` (`processo_extrajudicial_id`),
  KEY `fk_paex_criado_por` (`criado_por`),
  CONSTRAINT `fk_paex_administrativo` FOREIGN KEY (`processo_administrativo_id`) REFERENCES `processos_administrativos` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_paex_criado_por` FOREIGN KEY (`criado_por`) REFERENCES `usuarios` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_paex_extrajudicial` FOREIGN KEY (`processo_extrajudicial_id`) REFERENCES `processos_extrajudiciais` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

